CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NULL UNIQUE,username VARCHAR(100) NULL UNIQUE,phone VARCHAR(40),password VARCHAR(255) NOT NULL,status ENUM('active','suspended','invited') NOT NULL DEFAULT 'active',last_login_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE roles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,code VARCHAR(100) NOT NULL UNIQUE,description TEXT,is_system_role BOOLEAN DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE permissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,code VARCHAR(150) NOT NULL UNIQUE,module VARCHAR(100) NOT NULL,description TEXT,created_at DATETIME NOT NULL,INDEX(module)) ENGINE=InnoDB;
CREATE TABLE role_user(user_id BIGINT UNSIGNED NOT NULL,role_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(user_id,role_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE permission_role(role_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE countries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,iso2 CHAR(2) NOT NULL UNIQUE,iso3 CHAR(3),name_fa VARCHAR(150) NOT NULL,name_en VARCHAR(150),is_active BOOLEAN DEFAULT 1,created_at DATETIME,updated_at DATETIME,INDEX(name_fa)) ENGINE=InnoDB;
CREATE TABLE currencies(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code CHAR(3) NOT NULL UNIQUE,name_fa VARCHAR(100),name_en VARCHAR(100),symbol VARCHAR(20),decimal_places TINYINT DEFAULT 2,is_active BOOLEAN DEFAULT 1,created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB;
CREATE TABLE units(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,name_fa VARCHAR(100),name_en VARCHAR(100),dimension VARCHAR(50),is_active BOOLEAN DEFAULT 1,created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB;
CREATE TABLE industries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,parent_id BIGINT UNSIGNED NULL,code VARCHAR(60),name_fa VARCHAR(160) NOT NULL,name_en VARCHAR(160),description TEXT,is_active BOOLEAN DEFAULT 1,created_at DATETIME,updated_at DATETIME,FOREIGN KEY(parent_id) REFERENCES industries(id) ON DELETE RESTRICT,INDEX(name_fa)) ENGINE=InnoDB;
CREATE TABLE product_categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,parent_id BIGINT UNSIGNED NULL,code VARCHAR(60) NOT NULL UNIQUE,name_fa VARCHAR(160) NOT NULL,name_en VARCHAR(160),description TEXT,sort_order INT DEFAULT 0,is_active BOOLEAN DEFAULT 1,created_at DATETIME,updated_at DATETIME,FOREIGN KEY(parent_id) REFERENCES product_categories(id) ON DELETE RESTRICT,INDEX(name_fa)) ENGINE=InnoDB;
CREATE TABLE products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,internal_code VARCHAR(80) NOT NULL UNIQUE,name_fa VARCHAR(190) NOT NULL,name_en VARCHAR(190),trade_name VARCHAR(190),category_id BIGINT UNSIGNED NULL,short_description TEXT,full_description LONGTEXT,default_unit_id BIGINT UNSIGNED NULL,status ENUM('draft','active','archived') DEFAULT 'active',created_by BIGINT UNSIGNED,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(category_id) REFERENCES product_categories(id) ON DELETE RESTRICT,FOREIGN KEY(default_unit_id) REFERENCES units(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,INDEX(name_fa),INDEX(name_en),FULLTEXT(name_fa,name_en,trade_name)) ENGINE=InnoDB;
CREATE TABLE product_aliases(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,alias VARCHAR(190) NOT NULL,language VARCHAR(10),alias_type VARCHAR(40),created_at DATETIME,UNIQUE(product_id,alias),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,INDEX(alias)) ENGINE=InnoDB;
CREATE TABLE product_attribute_definitions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NOT NULL,code VARCHAR(80) NOT NULL,label_fa VARCHAR(150) NOT NULL,label_en VARCHAR(150),data_type ENUM('text','decimal','integer','boolean','date','select') NOT NULL,unit_id BIGINT UNSIGNED,is_required BOOLEAN DEFAULT 0,is_filterable BOOLEAN DEFAULT 0,options_json JSON,sort_order INT DEFAULT 0,is_active BOOLEAN DEFAULT 1,created_at DATETIME,updated_at DATETIME,UNIQUE(category_id,code),FOREIGN KEY(category_id) REFERENCES product_categories(id) ON DELETE RESTRICT,FOREIGN KEY(unit_id) REFERENCES units(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE product_attribute_values(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,attribute_definition_id BIGINT UNSIGNED NOT NULL,value_text TEXT,value_decimal DECIMAL(24,8),value_integer BIGINT,value_boolean BOOLEAN,value_date DATE,unit_id BIGINT UNSIGNED,source_note TEXT,valid_from DATE,valid_until DATE,created_by BIGINT UNSIGNED,created_at DATETIME,updated_at DATETIME,UNIQUE(product_id,attribute_definition_id),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(attribute_definition_id) REFERENCES product_attribute_definitions(id) ON DELETE RESTRICT,FOREIGN KEY(unit_id) REFERENCES units(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE product_hs_codes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,country_id BIGINT UNSIGNED NULL,code VARCHAR(30) NOT NULL,code_level TINYINT,description TEXT,classification_status ENUM('suggested','under_review','confirmed','rejected','obsolete') DEFAULT 'suggested',valid_from DATE,valid_until DATE,source_name VARCHAR(190),source_url VARCHAR(500),reviewed_by BIGINT UNSIGNED,reviewed_at DATETIME,notes TEXT,created_by BIGINT UNSIGNED,created_at DATETIME,updated_at DATETIME,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE RESTRICT,FOREIGN KEY(country_id) REFERENCES countries(id) ON DELETE RESTRICT,FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,INDEX(code)) ENGINE=InnoDB;
CREATE TABLE companies(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,legal_name VARCHAR(190) NOT NULL,trade_name VARCHAR(190),country_id BIGINT UNSIGNED,state_region VARCHAR(150),city VARCHAR(150),address TEXT,website VARCHAR(255),registration_number VARCHAR(100),tax_number VARCHAR(100),company_type VARCHAR(80),verification_status ENUM('unverified','under_review','verified','rejected') DEFAULT 'unverified',description TEXT,internal_rating DECIMAL(3,1),status ENUM('active','archived') DEFAULT 'active',created_by BIGINT UNSIGNED,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME,FOREIGN KEY(country_id) REFERENCES countries(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,INDEX(legal_name),FULLTEXT(legal_name,trade_name)) ENGINE=InnoDB;
CREATE TABLE company_roles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,role_type ENUM('buyer','seller','manufacturer','intermediary','freight_forwarder','carrier','insurer','broker','laboratory','consultant','other') NOT NULL,notes TEXT,valid_from DATE,valid_until DATE,created_at DATETIME,UNIQUE(company_id,role_type),FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE contacts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(120),job_title VARCHAR(150),email VARCHAR(190),phone VARCHAR(50),mobile VARCHAR(50),preferred_language VARCHAR(10) DEFAULT 'fa',notes TEXT,status ENUM('active','archived') DEFAULT 'active',created_by BIGINT UNSIGNED,created_at DATETIME,updated_at DATETIME,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,INDEX(last_name)) ENGINE=InnoDB;
CREATE TABLE company_contacts(company_id BIGINT UNSIGNED NOT NULL,contact_id BIGINT UNSIGNED NOT NULL,relationship_title VARCHAR(150),is_primary BOOLEAN DEFAULT 0,valid_from DATE,valid_until DATE,notes TEXT,PRIMARY KEY(company_id,contact_id),FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT,FOREIGN KEY(contact_id) REFERENCES contacts(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE opportunity_stages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,code VARCHAR(100) NOT NULL UNIQUE,sort_order INT DEFAULT 0,is_terminal BOOLEAN DEFAULT 0,required_fields_json JSON,is_active BOOLEAN DEFAULT 1,created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB;
CREATE TABLE opportunities(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference_number VARCHAR(80) NOT NULL UNIQUE,title VARCHAR(255) NOT NULL,opportunity_type ENUM('purchase','sale','sourcing','logistics','other') DEFAULT 'other',status ENUM('open','on_hold','won','lost','cancelled','archived') DEFAULT 'open',stage_id BIGINT UNSIGNED NOT NULL,priority ENUM('low','normal','high','urgent') DEFAULT 'normal',description LONGTEXT,owner_user_id BIGINT UNSIGNED,created_by BIGINT UNSIGNED,start_date DATE NOT NULL,target_close_date DATE,closed_at DATETIME,outcome_reason TEXT,confidentiality_level ENUM('team','restricted') DEFAULT 'team',estimated_amount DECIMAL(24,4),currency_id BIGINT UNSIGNED,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME,FOREIGN KEY(stage_id) REFERENCES opportunity_stages(id) ON DELETE RESTRICT,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(currency_id) REFERENCES currencies(id) ON DELETE RESTRICT,INDEX(title),INDEX(status),INDEX(target_close_date),FULLTEXT(title,description)) ENGINE=InnoDB;
CREATE TABLE opportunity_stage_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,opportunity_id BIGINT UNSIGNED NOT NULL,from_stage_id BIGINT UNSIGNED,to_stage_id BIGINT UNSIGNED NOT NULL,changed_by BIGINT UNSIGNED NOT NULL,changed_at DATETIME NOT NULL,reason TEXT,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE RESTRICT,FOREIGN KEY(from_stage_id) REFERENCES opportunity_stages(id) ON DELETE RESTRICT,FOREIGN KEY(to_stage_id) REFERENCES opportunity_stages(id) ON DELETE RESTRICT,FOREIGN KEY(changed_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE opportunity_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,opportunity_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(24,8) NOT NULL,unit_id BIGINT UNSIGNED NOT NULL,requested_specifications TEXT,packaging VARCHAR(255),origin_country_id BIGINT UNSIGNED,destination_country_id BIGINT UNSIGNED,notes TEXT,created_at DATETIME,updated_at DATETIME,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE RESTRICT,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE RESTRICT,FOREIGN KEY(unit_id) REFERENCES units(id) ON DELETE RESTRICT,FOREIGN KEY(origin_country_id) REFERENCES countries(id) ON DELETE RESTRICT,FOREIGN KEY(destination_country_id) REFERENCES countries(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE opportunity_parties(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,opportunity_id BIGINT UNSIGNED NOT NULL,company_id BIGINT UNSIGNED NOT NULL,contact_id BIGINT UNSIGNED,party_role ENUM('buyer','seller','manufacturer','intermediary','agent','other') NOT NULL,relationship_status VARCHAR(80),notes TEXT,created_at DATETIME,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE RESTRICT,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT,FOREIGN KEY(contact_id) REFERENCES contacts(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE opportunity_tasks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,opportunity_id BIGINT UNSIGNED,title VARCHAR(255) NOT NULL,description TEXT,assigned_to BIGINT UNSIGNED NOT NULL,created_by BIGINT UNSIGNED NOT NULL,due_at DATETIME,priority ENUM('low','normal','high','urgent') DEFAULT 'normal',status ENUM('open','in_progress','done','cancelled') DEFAULT 'open',completed_at DATETIME,completed_by BIGINT UNSIGNED,created_at DATETIME,updated_at DATETIME,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE RESTRICT,FOREIGN KEY(assigned_to) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(completed_by) REFERENCES users(id) ON DELETE RESTRICT,INDEX(due_at),INDEX(status)) ENGINE=InnoDB;
CREATE TABLE activities(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,opportunity_id BIGINT UNSIGNED,company_id BIGINT UNSIGNED,contact_id BIGINT UNSIGNED,activity_type ENUM('call','meeting','email_note','message_note','internal_note','status_change','document_event','other') DEFAULT 'other',subject VARCHAR(255) NOT NULL,body TEXT,occurred_at DATETIME NOT NULL,created_by BIGINT UNSIGNED NOT NULL,visibility ENUM('team','restricted') DEFAULT 'team',created_at DATETIME,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE RESTRICT,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT,FOREIGN KEY(contact_id) REFERENCES contacts(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE price_observations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,company_id BIGINT UNSIGNED,opportunity_id BIGINT UNSIGNED,price_type ENUM('asking','offer','indicative','historical','target','purchase_cost','selling_price') NOT NULL,amount DECIMAL(24,8) NOT NULL,currency_id BIGINT UNSIGNED NOT NULL,unit_id BIGINT UNSIGNED NOT NULL,minimum_quantity DECIMAL(24,8),country_id BIGINT UNSIGNED,incoterm_code VARCHAR(10),observed_at DATETIME NOT NULL,valid_until DATE,source_type ENUM('user_entered','document','internal_calculation') DEFAULT 'user_entered',source_description TEXT,notes TEXT,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME,updated_at DATETIME,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE RESTRICT,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE RESTRICT,FOREIGN KEY(currency_id) REFERENCES currencies(id) ON DELETE RESTRICT,FOREIGN KEY(unit_id) REFERENCES units(id) ON DELETE RESTRICT,FOREIGN KEY(country_id) REFERENCES countries(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE quotations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference_number VARCHAR(80) NOT NULL UNIQUE,opportunity_id BIGINT UNSIGNED NOT NULL,company_id BIGINT UNSIGNED NOT NULL,quotation_direction ENUM('received','sent') NOT NULL,quotation_date DATE NOT NULL,valid_until DATE,currency_id BIGINT UNSIGNED NOT NULL,status ENUM('draft','received','under_review','accepted','rejected','expired') DEFAULT 'draft',payment_terms TEXT,delivery_terms TEXT,notes TEXT,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME,updated_at DATETIME,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE RESTRICT,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT,FOREIGN KEY(currency_id) REFERENCES currencies(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE quotation_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,quotation_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(24,8) NOT NULL,unit_id BIGINT UNSIGNED NOT NULL,unit_price DECIMAL(24,8) NOT NULL,discount_amount DECIMAL(24,8) DEFAULT 0,line_total DECIMAL(24,8) NOT NULL,incoterm_code VARCHAR(10),notes TEXT,FOREIGN KEY(quotation_id) REFERENCES quotations(id) ON DELETE RESTRICT,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE RESTRICT,FOREIGN KEY(unit_id) REFERENCES units(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE transport_methods(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,name_fa VARCHAR(100) NOT NULL,name_en VARCHAR(100),description TEXT,is_active BOOLEAN DEFAULT 1,created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB;
CREATE TABLE transport_routes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,origin_country_id BIGINT UNSIGNED NOT NULL,destination_country_id BIGINT UNSIGNED NOT NULL,description TEXT,status ENUM('draft','active','archived') DEFAULT 'active',created_by BIGINT UNSIGNED,created_at DATETIME,updated_at DATETIME,FOREIGN KEY(origin_country_id) REFERENCES countries(id) ON DELETE RESTRICT,FOREIGN KEY(destination_country_id) REFERENCES countries(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,INDEX(name)) ENGINE=InnoDB;
CREATE TABLE transport_route_legs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,route_id BIGINT UNSIGNED NOT NULL,sequence INT NOT NULL,from_location VARCHAR(190) NOT NULL,to_location VARCHAR(190) NOT NULL,transport_method_id BIGINT UNSIGNED NOT NULL,border_port_terminal VARCHAR(190),estimated_duration_days DECIMAL(8,2),estimated_cost DECIMAL(24,8),currency_id BIGINT UNSIGNED,notes TEXT,UNIQUE(route_id,sequence),FOREIGN KEY(route_id) REFERENCES transport_routes(id) ON DELETE RESTRICT,FOREIGN KEY(transport_method_id) REFERENCES transport_methods(id) ON DELETE RESTRICT,FOREIGN KEY(currency_id) REFERENCES currencies(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE transport_quotes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,opportunity_id BIGINT UNSIGNED,route_id BIGINT UNSIGNED,company_id BIGINT UNSIGNED NOT NULL,transport_method_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(24,8) NOT NULL,currency_id BIGINT UNSIGNED NOT NULL,quoted_at DATETIME NOT NULL,valid_until DATE,estimated_duration_days DECIMAL(8,2),conditions TEXT,source_note TEXT,status VARCHAR(50),created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME,updated_at DATETIME,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE RESTRICT,FOREIGN KEY(route_id) REFERENCES transport_routes(id) ON DELETE RESTRICT,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT,FOREIGN KEY(transport_method_id) REFERENCES transport_methods(id) ON DELETE RESTRICT,FOREIGN KEY(currency_id) REFERENCES currencies(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE insurance_products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,coverage_type VARCHAR(100),coverage_description TEXT,exclusions TEXT,supported_transport_methods VARCHAR(255),countries_json JSON,is_active BOOLEAN DEFAULT 1,created_at DATETIME,updated_at DATETIME,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE insurance_quotes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,opportunity_id BIGINT UNSIGNED NOT NULL,insurance_product_id BIGINT UNSIGNED,company_id BIGINT UNSIGNED NOT NULL,insured_value DECIMAL(24,8) NOT NULL,currency_id BIGINT UNSIGNED NOT NULL,premium_amount DECIMAL(24,8),premium_rate DECIMAL(12,8),valid_until DATE,coverage_summary TEXT,exclusions TEXT,status VARCHAR(50),created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME,updated_at DATETIME,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE RESTRICT,FOREIGN KEY(insurance_product_id) REFERENCES insurance_products(id) ON DELETE RESTRICT,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT,FOREIGN KEY(currency_id) REFERENCES currencies(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE files(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,original_name VARCHAR(255) NOT NULL,storage_path VARCHAR(500) NOT NULL,mime_type VARCHAR(150) NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL,sha256 CHAR(64) NOT NULL,uploaded_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,FOREIGN KEY(uploaded_by) REFERENCES users(id) ON DELETE RESTRICT,INDEX(sha256)) ENGINE=InnoDB;
CREATE TABLE document_templates(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(190) NOT NULL,document_type VARCHAR(80) NOT NULL,language VARCHAR(10) DEFAULT 'fa',template_version INT DEFAULT 1,template_file_id BIGINT UNSIGNED,field_schema_json JSON,is_active BOOLEAN DEFAULT 1,created_by BIGINT UNSIGNED,created_at DATETIME,updated_at DATETIME,FOREIGN KEY(template_file_id) REFERENCES files(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE documents(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference_number VARCHAR(80) NOT NULL UNIQUE,document_type ENUM('loi','pi','rfq','quotation','purchase_order','product_specification','internal_report','other') NOT NULL,title VARCHAR(255) NOT NULL,opportunity_id BIGINT UNSIGNED,company_id BIGINT UNSIGNED,status ENUM('draft','review','approved','issued','expired','archived') DEFAULT 'draft',language VARCHAR(10) DEFAULT 'fa',currency_id BIGINT UNSIGNED,template_id BIGINT UNSIGNED,current_version INT DEFAULT 1,issued_at DATETIME,expires_at DATETIME,created_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED,created_at DATETIME,updated_at DATETIME,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE RESTRICT,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT,FOREIGN KEY(currency_id) REFERENCES currencies(id) ON DELETE RESTRICT,FOREIGN KEY(template_id) REFERENCES document_templates(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE document_versions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NOT NULL,version_number INT NOT NULL,file_id BIGINT UNSIGNED,content_snapshot_json JSON NOT NULL,change_summary TEXT,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,UNIQUE(document_id,version_number),FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE RESTRICT,FOREIGN KEY(file_id) REFERENCES files(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,type VARCHAR(80),title VARCHAR(190) NOT NULL,body TEXT,related_entity_type VARCHAR(80),related_entity_id BIGINT UNSIGNED,read_at DATETIME,created_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,INDEX(user_id,read_at)) ENGINE=InnoDB;
CREATE TABLE company_settings(setting_key VARCHAR(120) PRIMARY KEY,setting_value LONGTEXT,updated_by BIGINT UNSIGNED,updated_at DATETIME,FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,action VARCHAR(80) NOT NULL,entity_type VARCHAR(100) NOT NULL,entity_id VARCHAR(100) NOT NULL,old_values_json JSON,new_values_json JSON,ip_address VARCHAR(45),created_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,INDEX(entity_type,entity_id),INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE ai_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(190),created_at DATETIME,updated_at DATETIME,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE ai_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,session_id BIGINT UNSIGNED NOT NULL,role ENUM('user','assistant','system') NOT NULL,content LONGTEXT NOT NULL,related_entity_type VARCHAR(80),related_entity_id BIGINT UNSIGNED,created_at DATETIME,FOREIGN KEY(session_id) REFERENCES ai_sessions(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE exchange_rates(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,base_currency_id BIGINT UNSIGNED NOT NULL,quote_currency_id BIGINT UNSIGNED NOT NULL,rate DECIMAL(24,10) NOT NULL,rate_date DATE NOT NULL,source VARCHAR(190) NOT NULL,entered_by BIGINT UNSIGNED NOT NULL,notes TEXT,created_at DATETIME,FOREIGN KEY(base_currency_id) REFERENCES currencies(id) ON DELETE RESTRICT,FOREIGN KEY(quote_currency_id) REFERENCES currencies(id) ON DELETE RESTRICT,FOREIGN KEY(entered_by) REFERENCES users(id) ON DELETE RESTRICT,UNIQUE(base_currency_id,quote_currency_id,rate_date,source)) ENGINE=InnoDB;
